// ---------- amount parsing (Indonesian conventions, whole rupiah) ----------
// "25rb" "25k" "25 ribu" = 25 000, "1,5jt" "1.5jt" "1,5 juta" = 1 500 000, "Rp 25.000", "1.250.000", "1,250,000", "25.000,50"
const parseAmount = raw => {
  const s = String(raw).trim().toLowerCase().replace(/^rp\.?/, '');
  const m = /^([\d.,]+)(k|rb|ribu|jt|juta|miliar)?$/.exec(s);
  if (!m) return null;
  const num = m[1], suffix = m[2];
  const mult = { k: 1e3, rb: 1e3, ribu: 1e3, jt: 1e6, juta: 1e6, miliar: 1e9 }[suffix] || 1;
  let value;
  if (suffix) {
    if (!/^\d+([.,]\d{1,3})?$/.test(num)) return null;              // with a suffix a single separator is a decimal point
    value = parseFloat(num.replace(',', '.'));
  } else if (/^\d+$/.test(num)) value = Number(num);
  else if (/^\d{1,3}([.,]\d{3})+$/.test(num)) value = Number(num.replace(/[.,]/g, ''));                 // 1.250.000 or 1,250,000
  else if (/^\d{1,3}(\.\d{3})*,\d{1,2}$/.test(num)) value = parseFloat(num.replace(/\./g, '').replace(',', '.'));   // 1.250,50
  else if (/^\d{1,3}(,\d{3})*\.\d{1,2}$/.test(num)) value = parseFloat(num.replace(/,/g, ''));          // 1,250.50
  else if (/^\d+[.,]\d{1,2}$/.test(num)) value = parseFloat(num.replace(',', '.'));                       // 25000.50
  else return null;
  const v = Math.round(value * mult);
  return Number.isFinite(v) && v >= 1 && v <= 1e12 ? v : null;
};

const ALLOWED_CHAT_IDS = ['REPLACE_WITH_ALLOWED_CHAT_ID'];    // household members who may use the bot. Fail closed: the placeholder authorizes nobody.
const msg = ($input.first().json || {}).message;
if (!msg || typeof msg.text !== 'string' || !msg.chat) return [{ json: { action: 'ignore' } }];
const chat = String(msg.chat.id);
const reply = text => [{ json: { chat_id: chat, action: 'reply', reply: text } }];
if (!ALLOWED_CHAT_IDS.includes(chat)) return reply('Not authorized. Your chat id is ' + chat + '. Add it to ALLOWED_CHAT_IDS in the "Parse Message" node.');

const HELP = ['Finance tracker', '',
  'Just send a message:', '  25rb makan siang', '  grab 38.000 #transport', '  +5jt gaji   (income)', '',
  'Amounts: 25000, 25.000, Rp25.000, 25rb, 25k, 1,5jt, 2 juta', 'Add #category to choose the category, otherwise keywords decide.', '',
  'Commands:', '/month  month to date vs budgets', '/today  today', '/undo  remove your last entry (within 30 min)',
  '/budget food 2jt  set a monthly budget (/budget food off to remove)', '/rule grab transport  teach a keyword', '/in 5jt gaji   record income'].join('\n');
const CAT_RE = /^[a-z0-9-]{1,20}$/;
const prep = s => s.replace(/\bRp\.?\s+(?=\d)/gi, 'Rp').replace(/(\d)\s+(rb|ribu|k|jt|juta|miliar)\b/gi, '$1$2');
const clean = (v, max) => String(v).replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);

const entry = (rest, kind) => {
  let text = prep(rest);
  let tag = '';
  const tm = /(?:^|\s)#([a-z0-9-]{1,20})(?=\s|$)/i.exec(text);
  if (tm) { tag = tm[1].toLowerCase(); text = text.replace(tm[0], ' '); }
  const tokens = text.split(/\s+/).filter(Boolean);
  let idx = -1, amount = null;
  for (const i of [0, tokens.length - 1]) { if (i >= 0 && amount === null) { const a = parseAmount(tokens[i]); if (a !== null) { amount = a; idx = i; } } }
  if (amount === null) return reply('I could not find an amount. Examples: "25rb makan siang", "grab 38.000 #transport", "+5jt gaji".');
  const note = clean(tokens.filter((_, i) => i !== idx).join(' '), 200) || '-';
  return [{ json: { chat_id: chat, action: 'record', kind, amount, note, tag } }];
};

const text = msg.text.trim().slice(0, 500);
const mm = /^\/([a-zA-Z_]+)(?:@\w+)?(?:\s+([\s\S]*))?$/.exec(text);
if (!mm) {
  if (!text) return [{ json: { action: 'ignore' } }];
  return text.startsWith('+') ? entry(text.slice(1), 'income') : entry(text, 'expense');
}
const cmd = mm[1].toLowerCase(), rest = (mm[2] || '').trim();
switch (cmd) {
  case 'start': case 'help': return reply(HELP);
  case 'spend': case 's': case 'out': return entry(rest, 'expense');
  case 'in': case 'income': return entry(rest, 'income');
  case 'month': return [{ json: { chat_id: chat, action: 'month' } }];
  case 'today': return [{ json: { chat_id: chat, action: 'today' } }];
  case 'undo': return [{ json: { chat_id: chat, action: 'undo' } }];
  case 'budget': {
    const t = prep(rest).split(/\s+/).filter(Boolean);
    const category = (t[0] || '').toLowerCase();
    if (!CAT_RE.test(category) || t.length < 2) return reply('Usage: /budget food 2jt   or   /budget food off');
    const arg = t.slice(1).join('').toLowerCase();
    const amount = ['off', 'remove', '0'].includes(arg) ? 0 : parseAmount(arg);
    if (amount === null) return reply('I could not read that amount. Usage: /budget food 2jt');
    return [{ json: { chat_id: chat, action: 'budget', category, amount } }];
  }
  case 'rule': {
    const t = rest.toLowerCase().split(/\s+/).filter(Boolean);
    const category = t[t.length - 1] || '', keyword = t.slice(0, -1).join(' ');
    if (t.length < 2 || !CAT_RE.test(category) || !/^[a-z0-9 ]{2,30}$/.test(keyword)) return reply('Usage: /rule grab transport   (keyword: letters and digits only, category: letters, digits, dash)');
    return [{ json: { chat_id: chat, action: 'rule', keyword, category } }];
  }
  default: return reply('Unknown command. Send /help to see what I can do.');
}

