WITH up AS (
  INSERT INTO budgets (category, monthly_amount) SELECT $1::text, $2::bigint WHERE $2::bigint > 0
  ON CONFLICT (category) DO UPDATE SET monthly_amount = EXCLUDED.monthly_amount
  RETURNING category, monthly_amount
), del AS (
  DELETE FROM budgets WHERE category = $1::text AND $2::bigint = 0 RETURNING category
)
SELECT (SELECT category FROM up) AS set_category, (SELECT monthly_amount FROM up)::bigint AS monthly_amount, EXISTS (SELECT 1 FROM del) AS removed;

INSERT INTO category_rules (keyword, category) VALUES ($1::text, $2::text)
ON CONFLICT (keyword) DO UPDATE SET category = EXCLUDED.category
RETURNING keyword, category, (xmax = 0) AS created;

WITH cfg AS (SELECT (now() AT TIME ZONE timezone)::date AS today FROM settings)
SELECT t.id, t.kind, t.amount::bigint AS amount, t.note, t.category, to_char(cfg.today, 'YYYY-MM-DD') AS today
FROM transactions t, cfg WHERE NOT t.deleted AND t.tx_date = cfg.today ORDER BY t.id LIMIT 30;

