const p = $('Parse Message').first().json;
if (p.action === 'ignore') return [];
const esc = x => String(x === null || x === undefined ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rp = n => 'Rp ' + String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const bar = pct => { const n = Math.max(0, Math.min(10, Math.round(pct / 10))); return '█'.repeat(n) + '░'.repeat(10 - n); };
const send = t => [{ json: { text: String(t).slice(0, 3800) } }];
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);

switch (p.action) {
  case 'reply': return send(esc(p.reply));
  case 'record': {
    const r = rows[0];
    if (!r || !r.id) return send('Could not save that entry. Please try again.');
    const L = [(r.kind === 'income' ? '💰 Income ' : '✅ Expense ') + rp(r.amount) + ' · ' + esc(r.category) + ' · #' + r.id];
    if (r.kind === 'expense' && r.budget !== null && r.budget !== undefined) {
      const pct = Math.round(100 * Number(r.month_spent) / Number(r.budget));
      L.push(esc(r.category) + ': ' + rp(r.month_spent) + ' of ' + rp(r.budget) + ' (' + pct + '%) ' + bar(pct));
    }
    const alerts = (r.alerts || []).map(Number);
    if (alerts.includes(100)) L.push('🔴 <b>Budget exceeded</b> for ' + esc(r.category));
    else if (alerts.includes(80)) L.push('🟠 <b>80% of the budget used</b> for ' + esc(r.category));
    return send(L.join('\n'));
  }
  case 'budget': {
    const r = rows[0] || {};
    if (r.set_category) return send('Budget for <b>' + esc(r.set_category) + '</b> set to ' + rp(r.monthly_amount) + ' per month.');
    if (r.removed) return send('Budget for ' + esc(p.category) + ' removed.');
    return send('There was no budget for ' + esc(p.category) + '.');
  }
  case 'rule': {
    const r = rows[0] || {};
    return r.keyword ? send((r.created ? 'Rule added: ' : 'Rule updated: ') + '"' + esc(r.keyword) + '" → <b>' + esc(r.category) + '</b>. It applies to new entries.') : send('Could not save the rule.');
  }
  case 'undo': {
    const r = rows[0];
    if (!r || !r.id) return send('Nothing to undo. Only your most recent entry from the last 30 minutes can be removed.');
    return send('↩️ Removed ' + (r.kind === 'income' ? 'income ' : 'expense ') + rp(r.amount) + ' · ' + esc(r.category) + ' · ' + esc(r.note) + '\n(Budget alerts already sent are not taken back.)');
  }
  case 'today': {
    const t = rows.filter(x => x.id);
    if (!t.length) return send('Nothing recorded today.');
    let spent = 0, income = 0;
    const L = ['📅 <b>Today</b> ' + esc(t[0].today), ''];
    for (const x of t) { if (x.kind === 'income') income += Number(x.amount); else spent += Number(x.amount);
      L.push((x.kind === 'income' ? '+' : '−') + rp(x.amount) + ' · ' + esc(x.category) + ' · ' + esc(x.note)); }
    L.push('', 'Spent ' + rp(spent) + (income ? ', income ' + rp(income) : ''));
    return send(L.join('\n'));
  }
  case 'month': {
    const r = rows.filter(x => x.category !== undefined);
    if (!r.length) return send('No transactions or budgets this month yet.');
    const dom = Number(r[0].dom), dim = Number(r[0].dim);
    let spent = 0, income = 0;
    const L = ['🗓 <b>This month</b> (day ' + dom + ' of ' + dim + ')', ''];
    for (const x of r) {
      const s = Number(x.spent), b = x.budget === null || x.budget === undefined ? null : Number(x.budget);
      spent += s; income += Number(x.income);
      if (s === 0 && b === null) continue;
      let line = esc(x.category) + ': ' + rp(s);
      if (b) { const pct = Math.round(100 * s / b); line += ' / ' + rp(b) + ' ' + bar(pct) + ' ' + pct + '%'; if (dom >= 5 && s <= b && s / dom * dim > b) line += ' ⚠️ on pace to exceed'; }
      L.push(line);
    }
    L.push('', 'Spent ' + rp(spent) + (income ? ' · income ' + rp(income) + ' · net ' + (income - spent < 0 ? '−' : '') + rp(Math.abs(income - spent)) : ''));
    if (dom >= 5 && spent) L.push('At this pace: about ' + rp(spent / dom * dim) + ' by month end');
    return send(L.join('\n'));
  }
}
return send('Done.');

// ---------- amount parsing (Indonesian conventions, whole rupiah) ----------
// "25rb" "25k" "25 ribu" = 25 000, "1,5jt" "1.5jt" "1,5 juta" = 1 500 000, "Rp 25.000", "1.250.000", "1,250,000", "25.000,50"
const parseAmount = raw => {
