const body = ($input.first().json || {}).body;
const bad = error => [{ json: { valid: false, error } }];
if (!body || typeof body !== 'object' || typeof body.csv !== 'string') return bad('JSON body with a "csv" string is required');
const text = body.csv.replace(/^﻿/, '');
if (text.length > 1000000) return bad('csv is larger than 1 MB');
const firstLine = text.split(/\r?\n/).find(l => l.trim()) || '';
const countOut = ch => { let n = 0, q = false; for (const c of firstLine) { if (c === '"') q = !q; else if (!q && c === ch) n++; } return n; };
const delim = [',', ';', '\t'].map(d => [d, countOut(d)]).sort((a, b) => b[1] - a[1])[0];
if (!delim[1]) return bad('could not detect the delimiter (comma, semicolon or tab) in the header line');
const rows = [];
{ let row = [], field = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else q = false; } else field += c; }
    else if (c === '"') q = true;
    else if (c === delim[0]) { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(field); field = ''; if (row.some(x => x.trim() !== '')) rows.push(row); row = []; }
    else field += c;
  }
  if (q) return bad('unterminated quote in csv');
  if (field !== '' || row.length) { row.push(field); if (row.some(x => x.trim() !== '')) rows.push(row); } }
if (rows.length < 2) return bad('csv needs a header row and at least one data row');
if (rows.length - 1 > 5000) return bad('more than 5000 rows; split the file');

const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const header = rows[0].map(norm);
const cols = body.columns && typeof body.columns === 'object' ? body.columns : {};
const ALIASES = { date: ['date', 'tanggal', 'tgl', 'transactiondate', 'postingdate', 'tanggaltransaksi'], description: ['description', 'keterangan', 'deskripsi', 'remarks', 'details', 'memo', 'uraian'],
  amount: ['amount', 'jumlah', 'nominal', 'mutasi', 'value'], debit: ['debit', 'debet', 'keluar', 'withdrawal'], credit: ['credit', 'kredit', 'masuk', 'deposit'] };
const find = k => { const want = cols[k] ? [norm(cols[k])] : ALIASES[k]; return header.findIndex(h => want.includes(h)); };
const iDate = find('date'), iDesc = find('description'), iAmt = find('amount'), iDeb = find('debit'), iCred = find('credit');
if (iDate < 0 || iDesc < 0 || (iAmt < 0 && iDeb < 0 && iCred < 0)) return bad('could not find the date, description and amount (or debit/credit) columns. Headers seen: ' + rows[0].map(h => h.trim()).join(' | ').slice(0, 200) + '. Use the "columns" option to map them.');

const order = body.date_order === 'mdy' ? 'mdy' : 'dmy';
const invert = body.invert_sign === true;
const p2 = n => String(n).padStart(2, '0');
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, mei: 5, may: 5, jun: 6, jul: 7, agu: 8, agt: 8, aug: 8, sep: 9, okt: 10, oct: 10, nov: 11, des: 12, dec: 12 };
const mk = (y, m, d) => { if (y < 100) y += 2000; if (y < 2000 || y > 2100 || m < 1 || m > 12 || d < 1 || d > 31) return null;
  const t = new Date(Date.UTC(y, m - 1, d)); return t.getUTCFullYear() === y && t.getUTCMonth() === m - 1 && t.getUTCDate() === d ? y + '-' + p2(m) + '-' + p2(d) : null; };
const parseDate = raw => { const s = String(raw).trim(); let m;
  if ((m = /^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})(?:[ T].*)?$/.exec(s))) return mk(+m[1], +m[2], +m[3]);
  if ((m = /^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2}|\d{4})(?:[ T].*)?$/.exec(s))) return order === 'mdy' ? mk(+m[3], +m[1], +m[2]) : mk(+m[3], +m[2], +m[1]);
  if ((m = /^(\d{1,2})[ ,\-]+([A-Za-z]{3,9})[ ,\-]+(\d{2}|\d{4})$/.exec(s))) { const mo = MONTHS[m[2].slice(0, 3).toLowerCase()]; return mo ? mk(+m[3], mo, +m[1]) : null; }
  return null; };
const readAmount = raw => {
  let s = String(raw === undefined ? '' : raw).trim(); if (!s) return null;
  let neg = false;
  if (/^\(.*\)$/.test(s)) { neg = true; s = s.slice(1, -1); }
  if (s[0] === '-') { neg = true; s = s.slice(1); } else if (s[0] === '+') s = s.slice(1);
  if (/\s*(db|dr)$/i.test(s)) { neg = true; s = s.replace(/\s*(db|dr)$/i, ''); } else if (/\s*cr$/i.test(s)) s = s.replace(/\s*cr$/i, '');
  s = s.replace(/idr|rp\.?/gi, '').replace(/\s/g, '');
  const v = parseAmount(s);
  return v === null ? null : { v, neg };
};
const clean = (v, max) => String(v === undefined ? '' : v).replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);

const out = [], errors = []; let skipped = 0;
const seen = new Map();
const skip = (line, why) => { skipped++; if (errors.length < 5) errors.push('line ' + line + ': ' + why); };
for (let i = 1; i < rows.length; i++) {
  const r = rows[i], line = i + 1;
  const date = parseDate(r[iDate]);
  if (!date) { skip(line, 'invalid date "' + clean(r[iDate], 30) + '"'); continue; }
