  if (iAmt >= 0) {
    const a = readAmount(r[iAmt]);
    if (!a) { skip(line, 'invalid amount "' + clean(r[iAmt], 30) + '"'); continue; }
    kind = a.neg !== invert ? 'expense' : 'income'; amount = a.v;
  } else {
    const d = iDeb >= 0 ? readAmount(r[iDeb]) : null, c = iCred >= 0 ? readAmount(r[iCred]) : null;
    if (d && c) { skip(line, 'both debit and credit filled'); continue; }
