    kind = d ? 'expense' : 'income'; amount = (d || c).v;
  }
  const note = clean(r[iDesc], 200) || '-';
  const key = [date, kind, amount, note.toLowerCase()].join('|');
  const occ = (seen.get(key) || 0) + 1; seen.set(key, occ);
  out.push({ tx_date: date, kind, amount, note, occ });
}
if (!out.length) return bad('no importable rows. ' + errors.join('; '));
return [{ json: { valid: true, rows: out, rows_json: JSON.stringify(out), rows_in_file: rows.length - 1, skipped, errors } }];

const esc = x => String(x === null || x === undefined ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rp = n => 'Rp ' + String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const bar = pct => { const n = Math.max(0, Math.min(10, Math.round(pct / 10))); return '█'.repeat(n) + '░'.repeat(10 - n); };
const month = $('Month Status').all().map(i => i.json).filter(r => r && r.category !== undefined);
const week = $('Week Activity').all().map(i => i.json).filter(r => r && r.section);
const hist = $input.all().map(i => i.json).filter(r => r && r.tx_date);
const today = (month[0] && month[0].today) || new Date().toISOString().slice(0, 10);

// ---------- recurring payments (subscriptions, rent, installments) ----------
const DAYMS = 86400000;
const dayNum = s => Math.floor(Date.parse(s + 'T00:00:00Z') / DAYMS);
const dayStr = n => new Date(n * DAYMS).toISOString().slice(0, 10);
const STOP = new Set(['payment', 'pembayaran', 'bayar', 'trf', 'transfer', 'pmt', 'debit', 'kartu', 'card', 'autodebit', 'recurring', 'langganan', 'bulan', 'bulanan', 'monthly', 'the', 'for', 'dan', 'and']);
const merchantOf = note => (String(note).toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/).filter(w => w.length >= 3 && !STOP.has(w))[0]) || '';
const addMonth = s => { const [y, m, d] = s.split('-').map(Number); const ny = m === 12 ? y + 1 : y, nm = m === 12 ? 1 : m + 1;
  const dim = new Date(Date.UTC(ny, nm, 0)).getUTCDate(); return ny + '-' + String(nm).padStart(2, '0') + '-' + String(Math.min(d, dim)).padStart(2, '0'); };
const median = a => { const s = [...a].sort((x, y) => x - y), m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const detectRecurring = (items, todayStr) => {
  const byMerchant = new Map();
  for (const t of items) { const k = merchantOf(t.note); if (!k) continue; if (!byMerchant.has(k)) byMerchant.set(k, []); byMerchant.get(k).push({ amount: Number(t.amount), day: dayNum(t.tx_date) }); }
  const found = [];
  for (const [merchant, list] of byMerchant) {
    list.sort((a, b) => a.amount - b.amount);
    const clusters = [];                                   // same merchant, similar amount (within 5 % of the cluster's first amount)
    for (const t of list) { const c = clusters[clusters.length - 1]; if (c && t.amount <= c[0].amount * 1.05) c.push(t); else clusters.push([t]); }
    for (const c of clusters) {
      if (c.length < 3) continue;
      const days = [...new Set(c.map(t => t.day))].sort((a, b) => a - b);
      if (days.length < 3) continue;
      const gaps = days.slice(1).map((d, i) => d - days[i]);
      const M = median(gaps);
      const every = M >= 26 && M <= 35 ? 'monthly' : (M >= 6 && M <= 8 ? 'weekly' : null);
      if (!every) continue;
      const tol = every === 'monthly' ? 4 : 1;
      if (gaps.filter(g => Math.abs(g - M) <= tol).length < Math.max(2, Math.ceil(gaps.length * 0.6))) continue;   // tolerates one stray charge
      const last = days[days.length - 1];
